// Reference solution
function algToUse(header, keyring) {
  if (!header.kid) return 'NO_KID';
  var key = keyring[header.kid];
  if (!key) return 'UNKNOWN_KID';
  if (header.alg !== key.alg) return 'ALG_MISMATCH';
  return key.alg;
}
